fact_reviews = df_reviews.join(
    df_customers.select("customer_id"), on="customer_id", how="inner"
).join(
    df_products.select("product_id"), on="product_id", how="inner"
).withColumn(
    "date_id",
    date_format(col("review_date"), "yyyyMMdd").cast("integer")
)

print(f"Nombre de lignes : {fact_reviews.count()}")  
fact_reviews.show(5)

fact_inventory = df_inventory.join(
    df_products.select("product_id"), on="product_id", how="inner"
).join(
    df_warehouses.select("warehouse_id"), on="warehouse_id", how="inner"
).withColumn(
    "date_id",
    date_format(col("last_restock_date"), "yyyyMMdd").cast("integer")
)

print(f"Nombre de lignes : {fact_inventory.count()}")  
fact_inventory.show(5)
